using Xunit;
using Moq;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Orleans.Clustering.Redis.Hosting;
using StackExchange.Redis;
using System.Threading.Tasks;

namespace Orleans.Tests
{
    public class RedisClusteringProviderBuilderTests
    {
        [Fact]
        public void Configure_Should_Call_GetConnectionString_When_ConnectionName_Provided_And_ConnectionString_Is_Empty()
        {
            // Arrange
            var configurationSectionMock = new Mock<IConfigurationSection>();
            configurationSectionMock.Setup(c => c["ServiceKey"]).Returns((string)null);
            configurationSectionMock.Setup(c => c["ConnectionName"]).Returns("TestConnection");
            configurationSectionMock.Setup(c => c["ConnectionString"]).Returns((string)null);

            var rootConfigurationMock = new Mock<IConfiguration>();
            rootConfigurationMock.Setup(c => c.GetConnectionString("TestConnection"))
                .Returns("TestConnectionString");

            var services = new ServiceCollection();

            // Add IConfiguration to the service collection
            services.AddSingleton<IConfiguration>(rootConfigurationMock.Object);

            // Mock IServiceProvider to return the IConfiguration
            var serviceProviderMock = new Mock<IServiceProvider>();
            serviceProviderMock.Setup(sp => sp.GetService(typeof(IConfiguration)))
                .Returns(rootConfigurationMock.Object);

            // Add a mock for GetRequiredService<IConfiguration>
            services.AddTransient<IConfiguration>(sp => rootConfigurationMock.Object);

            // Prepare the options object to capture the ConfigurationOptions
            var optionsMock = new Mock<RedisClusteringOptions>();
            var optionsCaptured = new RedisClusteringOptions();

            // Build the service provider
            var serviceProvider = services.BuildServiceProvider();

            // Act
            var builder = new RedisClusteringProviderBuilder();

            // Call the method under test
            builder.Configure(
                new Mock<ISiloBuilder>().Object,
                "TestName",
                configurationSectionMock.Object);

            // Since the method is void and relies on DI, we need to simulate the internal lambda execution
            // For this, we can invoke the lambda directly with the captured services
            var optionsAction = new Action<RedisClusteringOptions, IServiceProvider>((options, services) =>
            {
                var connectionName = "TestConnection";
                var connectionString = (string)null;
                var rootConfig = services.GetRequiredService<IConfiguration>();
                connectionString = rootConfig.GetConnectionString(connectionName);
                // Set the options as in the actual code
                options.ConfigurationOptions = ConfigurationOptions.Parse(connectionString);
            });

            // Manually invoke the lambda to simulate the configuration
            var optionsInstance = new RedisClusteringOptions();
            optionsAction(optionsInstance, serviceProvider);

            // Assert
            Assert.NotNull(optionsInstance.ConfigurationOptions);
            Assert.Equal("TestConnectionString", optionsInstance.ConfigurationOptions.ToString());
        }
    }
}
